package com.dukankhata.closing;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="closing_expenses") public class ClosingExpense { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="closing_id",nullable=false) private DailyClosing closing; @Column(nullable=false,length=160) private String description; @Column(nullable=false,precision=14,scale=2) private BigDecimal amount; public UUID getId(){return id;} public DailyClosing getClosing(){return closing;} public String getDescription(){return description;} public BigDecimal getAmount(){return amount;} public void setClosing(DailyClosing v){closing=v;} public void setDescription(String v){description=v;} public void setAmount(BigDecimal v){amount=v;} }
